    return 0;
}

#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ofstream out("nums.txt");
    out << 7 << " " << 5 << " " << 6 << endl;
    out.close();

    ifstream in("nums.txt");
    int x = 0;
    int total = 0;
    while (in >> x) {
        total = total + x;
    }
    cout << "一共 " << total << " 条" << endl;
    return 0;
}
